// DewfordTown_Hall (zone 26): generated by converter/gen_interior_recipes_houses.py (Sapphire's simple people, signs
// and furniture messages). Messages: src/text/script/0032_room_DewfordTown_Hall.txt
// Story (chapter Ch2, Sapphire data/maps/DewfordTown_Hall/scripts.inc) after the "// ---- story" line (the generator
// placed nobody here): scripts 1-11, text lines 0-25. People (uids = Sapphire local ids) and the bookshelf/painting:
// data/story/ch2.json. Room origin (1,1). Script 11, the Sludge Bomb man (hidden until Norman is beaten), is chapter
// Ch6's beat: scenes/DewfordTown_Hall_SludgeBomb.inc.
// Every person here talks about Dewford's trendy phrase, an Easy Chat phrase Black 2 has no equivalent for
// (notes/STORY_COMMON.md: S_optional): the text file names the same fixed stand-in phrase as the trendy-phrase boy in
// Dewford ("Hot Idol", Sapphire's first Easy Chat words of the trend's two groups), the man's random hobby/lifestyle
// word is "Chores" (first word of EC_GROUP_LIFESTYLE), and the phrase's painting/debate number
// (GetDewfordHallPaintingNameIndex = (word0 + word1) & 7) is the one of that phrase: 0. Not "boring" (a new trend).
#include "asm/field_script.inc"
#include "hoenn.h"
#include "hoenn_trainers.h"
#include "hoenn_story.inc"

    ScriptEntry HL_Girl             // 1: DewfordTown_Hall_EventScript_Girl
    ScriptEntry HL_Woman            // 2: DewfordTown_Hall_EventScript_Woman
    ScriptEntry HL_Man              // 3: DewfordTown_Hall_EventScript_Man
    ScriptEntry HL_ExpertM          // 4: DewfordTown_Hall_EventScript_ExpertM
    ScriptEntry HL_Twin             // 5: DewfordTown_Hall_EventScript_Twin
    ScriptEntry HL_LittleBoy        // 6: DewfordTown_Hall_EventScript_LittleBoy
    ScriptEntry HL_Bookshelf        // 7: DewfordTown_Hall_EventScript_Bookshelf (sign)
    ScriptEntry HL_Painting         // 8: DewfordTown_Hall_EventScript_Painting (sign)
    ScriptEntry HL_SchoolKidM       // 9: DewfordTown_Hall_EventScript_SchoolKidM
    ScriptEntry HL_PsychicM         // 10: DewfordTown_Hall_EventScript_PsychicM
    ScriptEntry HL_SludgeBombMan    // 11: DewfordTown_Hall_EventScript_SludgeBombMan (chapter Ch6)
    ScriptEntriesEnd
// ---- story
#define HL_EXPERT 4
#define HL_TWIN 5
#define HL_SCHOOLKID 7
#define HL_PSYCHIC 8
#define HL_DEBATER 0x8008           // VAR_0x8008: 0 the school kid was talked to, 1 the psychic

HL_Girl:                            // (IsTrendyPhraseBoring: no, a new trend)
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_msgbox 0                      // What's in vogue? Why, it has to be "Hot Idol"! ...
    h_release

HL_Woman:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_msgbox 2                      // I'm teaching my Pokémon about "Hot Idol," ...
    h_release

HL_Man:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_yesno 3, HLIB_TMP             // ...Is it true that there's a deep link between "Hot Idol" and "Chores"?
    h_goto_if_yes HLIB_TMP, L_HL_ConfirmTrendLink
    h_msgbox 5                      // What?! Is that so?! ...
    h_release
L_HL_ConfirmTrendLink:
    h_msgbox 4                      // Oh! So, my hunch was right! ...
    h_release

HL_ExpertM:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_msgbox 6                      // This whole business about "Hot Idol"... Isn't there a TV show on it?
    h_closemessage
    h_applymovement HL_EXPERT, Common_Movement_WalkInPlaceFastestUp
    h_waitmovement
    h_release

HL_Twin:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_msgbox 7                      // Across the sea... Is "Hot Idol" even more popular?
    h_closemessage
    h_applymovement HL_TWIN, Common_Movement_WalkInPlaceFastestUp
    h_waitmovement
    h_release

HL_LittleBoy:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_msgbox 8                      // I collect official "Hot Idol" licensed merchandise. ...
    h_release

HL_Bookshelf:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_msgbox_info 9                 // Identifying Good "Hot Idol" & Bad "Hot Idol"... ...
    h_closemessage
    h_release

HL_Painting:                        // painting number 0: "Hot Idol's Scream"
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_msgbox_info 10                // "Hot Idol's Scream" is the title.
    h_closemessage
    h_release

HL_SchoolKidM:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_setvar HL_DEBATER, 0
    VMJump L_HL_DoTrendDebate
HL_PsychicM:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_setvar HL_DEBATER, 1
L_HL_DoTrendDebate:                 // debate number 0: TrendDebate1
    VMCall Sub_HL_DebateReact1
    h_msgbox_actor 14, HL_PSYCHIC   // I saw "Hot Idol"! Cool, huh? ...
    h_closemessage
    VMCall Sub_HL_DebateReact2
    h_msgbox_actor 15, HL_SCHOOLKID // Oh, no, no, no. That alleged "Hot Idol" you claim to have seen...
    h_release

Sub_HL_DebateReact1:                // the psychic turns to the school kid; the player to the psychic
    h_applymovement HL_PSYCHIC, Mv_HL_PsychicWalkInPlaceLeft
    h_waitmovement
    h_goto_if_ne HL_DEBATER, 0, L_HL_Return
    h_getplayerfacing HLIB_TMP      // VAR_FACING 4 (east): already facing him
    h_goto_if_eq HLIB_TMP, 3, L_HL_Return
    h_applymovement 255, Common_Movement_WalkInPlaceFastestRight
    h_waitmovement
L_HL_Return:
    VMReturn

Sub_HL_DebateReact2:                // the school kid answers; the player turns back to whoever was talked to
    h_applymovement HL_SCHOOLKID, Mv_HL_SchoolKidWalkInPlaceRight
    h_waitmovement
    h_getplayerfacing HLIB_TMP
    h_goto_if_ne HL_DEBATER, 0, L_HL_PlayerReactEast
    h_goto_if_ne HLIB_TMP, 0, L_HL_ReactNotUp       // VAR_FACING 2 (north)
    h_applymovement 255, Common_Movement_WalkInPlaceFastestUp
    h_waitmovement
    VMReturn
L_HL_ReactNotUp:
    h_goto_if_ne HLIB_TMP, 1, L_HL_Return           // VAR_FACING 1 (south)
    h_applymovement 255, Common_Movement_WalkInPlaceFastestDown
    h_waitmovement
    VMReturn
L_HL_PlayerReactEast:               // the psychic was talked to: face him again unless already facing west
    h_goto_if_eq HLIB_TMP, 2, L_HL_Return
    h_applymovement 255, Common_Movement_WalkInPlaceFastestLeft
    h_waitmovement
    VMReturn

#include "scenes/DewfordTown_Hall_SludgeBomb.inc"

    .balign 4, 0
Mv_HL_PsychicWalkInPlaceLeft:
    walk_in_place_left
    step_end
Mv_HL_SchoolKidWalkInPlaceRight:
    walk_in_place_right
    step_end
#include "common/movement.inc"
